-- SOURCE tables.sql sha256=1f924c7c6a493072d47ec1759f4e80d8dea38798e2eadad253173bfded2d532d
-- Class sections belong to a program/year study semester, never to a subject.
CREATE TABLE public.class_sections (
    section_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    study_semester_id uuid NOT NULL,
    name text NOT NULL CHECK (length(btrim(name)) BETWEEN 1 AND 160),
    code text NOT NULL CHECK (length(btrim(code)) BETWEEN 1 AND 32
        AND code ~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$'),
    description text CHECK (length(description) <= 2000),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (study_semester_id, institution_id)
        REFERENCES public.study_semesters (study_semester_id, institution_id) ON DELETE RESTRICT,
    UNIQUE (section_id, institution_id)
);
CREATE UNIQUE INDEX academic_sections_context_code
    ON public.class_sections (institution_id, study_semester_id, lower(btrim(code)));
CREATE UNIQUE INDEX academic_sections_context_name
    ON public.class_sections (institution_id, study_semester_id, lower(btrim(name)));

CREATE TABLE public.section_subject_assignments (
    assignment_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    institution_id uuid NOT NULL REFERENCES public.institutions(institution_id) ON DELETE RESTRICT,
    section_id uuid NOT NULL,
    subject_id uuid NOT NULL,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (section_id, institution_id)
        REFERENCES public.class_sections (section_id, institution_id) ON DELETE RESTRICT,
    FOREIGN KEY (subject_id, institution_id)
        REFERENCES public.subjects (subject_id, institution_id) ON DELETE RESTRICT,
    UNIQUE (institution_id, section_id, subject_id)
);
CREATE INDEX academic_sections_assigned_subject
    ON public.section_subject_assignments (institution_id, subject_id);

COMMENT ON TABLE public.class_sections IS
    'Class-level sections; program and academic year derive from their immutable study semester.';
COMMENT ON TABLE public.section_subject_assignments IS
    'Multiple reusable subjects per class section; removal deactivates a link and preserves its subject.';

-- SOURCE permissions.sql sha256=92b6fb2f2c0c20044ae0d16ebc680706fd534cdfa63e05de2615874718317799
-- Exact institution-scoped permissions for the approved Stage 3 workflows only.
INSERT INTO public.permissions (code, name, description, scope, is_active)
SELECT resource || '.' || operation, title || ' ' || operation,
       'Academic Setup: ' || title || ' ' || operation, 'institution', true
FROM (VALUES ('sections', 'Class sections'), ('section_subjects', 'Section subject assignments'))
    AS resources(resource, title)
CROSS JOIN (VALUES ('read'), ('manage')) AS operations(operation)
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    scope = EXCLUDED.scope, is_active = true, updated_at = now();

INSERT INTO public.role_permissions (role_id, permission_id)
SELECT r.id, p.permission_id
FROM public.roles r CROSS JOIN public.permissions p
WHERE r.name = 'admin' AND p.code IN (
    'sections.read', 'sections.manage', 'section_subjects.read', 'section_subjects.manage'
)
ON CONFLICT (role_id, permission_id) DO NOTHING;

-- SOURCE validation.sql sha256=11f4cd1538415db46288b21f0ce2479b9c7ba44e3edf437cb4510901d95c607d
-- All Academic Setup generations serialize hierarchy changes with one tenant lock.
CREATE FUNCTION public.validate_academic_sections() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    item jsonb := to_jsonb(NEW);
    previous jsonb;
    key text;
    parent_active boolean;
    subject_active boolean;
    check_parent boolean := TG_OP = 'INSERT';
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || NEW.institution_id::text, 0)
    );
    IF TG_OP = 'UPDATE' THEN
        previous := to_jsonb(OLD);
        FOR key IN SELECT jsonb_object_keys(item) LOOP
            IF (key LIKE '%\_id' ESCAPE '\' OR key = 'created_at')
               AND item -> key IS DISTINCT FROM previous -> key THEN
                RAISE EXCEPTION 'Academic identity and ancestry are immutable' USING ERRCODE = '22023';
            END IF;
        END LOOP;
        check_parent := NEW.is_active AND NOT OLD.is_active;
    END IF;
    IF check_parent THEN
        PERFORM 1 FROM public.institutions i
        JOIN public.organizations o ON o.organization_id = i.organization_id
        WHERE i.institution_id = NEW.institution_id
          AND i.is_active AND i.status = 'active' AND o.status = 'active'
        FOR SHARE OF i, o;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Active institution and organization required' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF TG_TABLE_NAME = 'class_sections' THEN
        SELECT s.is_active AND p.is_active AND d.is_active AND y.is_active INTO parent_active
        FROM public.study_semesters s
        JOIN public.programs p ON p.program_id = s.program_id AND p.institution_id = s.institution_id
        JOIN public.departments d ON d.department_id = p.department_id
          AND d.institution_id = p.institution_id
        JOIN public.academic_years y ON y.academic_year_id = s.academic_year_id
          AND y.institution_id = s.institution_id
        WHERE s.study_semester_id = NEW.study_semester_id AND s.institution_id = NEW.institution_id
        FOR SHARE OF s, p, d, y;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Study semester not found in institution' USING ERRCODE = '23503';
        END IF;
        IF NOT NEW.is_active AND EXISTS (
            SELECT 1 FROM public.section_subject_assignments a
            WHERE a.section_id = NEW.section_id AND a.institution_id = NEW.institution_id AND a.is_active
        ) THEN
            RAISE EXCEPTION 'Remove active subject assignments first' USING ERRCODE = '23514';
        END IF;
        NEW.name := btrim(NEW.name);
        NEW.code := btrim(NEW.code);
    ELSE
        SELECT c.is_active AND s.is_active AND p.is_active AND d.is_active AND y.is_active
        INTO parent_active
        FROM public.class_sections c
        JOIN public.study_semesters s ON s.study_semester_id = c.study_semester_id
          AND s.institution_id = c.institution_id
        JOIN public.programs p ON p.program_id = s.program_id AND p.institution_id = s.institution_id
        JOIN public.departments d ON d.department_id = p.department_id
          AND d.institution_id = p.institution_id
        JOIN public.academic_years y ON y.academic_year_id = s.academic_year_id
          AND y.institution_id = s.institution_id
        WHERE c.section_id = NEW.section_id AND c.institution_id = NEW.institution_id
        FOR SHARE OF c, s, p, d, y;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Section not found in institution' USING ERRCODE = '23503';
        END IF;
        SELECT subject.is_active AND d.is_active INTO subject_active
        FROM public.subjects subject
        JOIN public.departments d ON d.department_id = subject.department_id
          AND d.institution_id = subject.institution_id
        WHERE subject.subject_id = NEW.subject_id AND subject.institution_id = NEW.institution_id
        FOR SHARE OF subject, d;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Subject not found in institution' USING ERRCODE = '23503';
        END IF;
        -- A subject from another department is reusable within this institution.
        parent_active := parent_active AND subject_active;
    END IF;
    IF check_parent AND NOT parent_active THEN
        RAISE EXCEPTION 'Active academic parents required' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' THEN NEW.created_at := now(); END IF;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

-- SOURCE parent_guards.sql sha256=33855a0b3e1bbdaffdca3e6da0867f703592ac64a97e3b3817c5d6375835884a
-- Add guards to Stage 2 tables without replacing any existing routine or source.
CREATE FUNCTION public.guard_academic_sections_parent() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || NEW.institution_id::text, 0)
    );
    IF NEW.is_active THEN RETURN NEW; END IF;
    IF TG_TABLE_NAME = 'study_semesters' THEN
        IF EXISTS (
            SELECT 1 FROM public.class_sections c
            WHERE c.study_semester_id = NEW.study_semester_id
              AND c.institution_id = NEW.institution_id AND c.is_active
        ) THEN
            RAISE EXCEPTION 'Deactivate dependent sections first' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'subjects' THEN
        IF EXISTS (
            SELECT 1 FROM public.section_subject_assignments a
            WHERE a.subject_id = NEW.subject_id
              AND a.institution_id = NEW.institution_id AND a.is_active
        ) THEN
            RAISE EXCEPTION 'Remove active subject assignments first' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DO $$
DECLARE entity text;
BEGIN
    FOREACH entity IN ARRAY ARRAY['study_semesters', 'subjects'] LOOP
        EXECUTE format('CREATE TRIGGER academic_sections_parent_guard BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_academic_sections_parent()', entity);
    END LOOP;
END;
$$;

-- SOURCE write.sql sha256=4740373dad48454e7f45da7bd637d9771d6d7162d2892db9e1341d2ed70bbaf0
CREATE FUNCTION public.manage_academic_sections(
    p_actor_user_id uuid, p_institution_id uuid, p_entity text, p_record_id uuid, p_payload jsonb
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
    relation_name text;
    id_column text;
    allowed text[];
    immutable text[];
    required text[];
    key text;
    kind text;
    before_row jsonb;
    after_row jsonb;
    effective jsonb;
    item_id uuid := COALESCE(p_record_id, gen_random_uuid());
    fields text;
    expressions text;
BEGIN
    CASE p_entity
    WHEN 'sections' THEN
        relation_name := 'class_sections';
        id_column := 'section_id';
        immutable := ARRAY['study_semester_id'];
        allowed := ARRAY['name', 'code', 'description', 'is_active'] || immutable;
        required := ARRAY['name', 'code', 'study_semester_id'];
    WHEN 'section_subjects' THEN
        relation_name := 'section_subject_assignments';
        id_column := 'assignment_id';
        immutable := ARRAY['section_id', 'subject_id'];
        allowed := CASE WHEN p_record_id IS NULL THEN immutable ELSE ARRAY['is_active'] END;
        required := immutable;
    ELSE RAISE EXCEPTION 'Unknown academic sections entity' USING ERRCODE = '22023';
    END CASE;
    PERFORM public.assert_academic_foundation_actor(p_actor_user_id, p_institution_id, p_entity);
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' OR p_payload = '{}'::jsonb THEN
        RAISE EXCEPTION 'Academic fields required' USING ERRCODE = '22023';
    END IF;
    IF p_record_id IS NULL AND NOT p_payload ?& required THEN
        RAISE EXCEPTION 'Required academic fields missing' USING ERRCODE = '22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(p_payload) LOOP
        IF NOT key = ANY(allowed) OR (p_record_id IS NOT NULL AND key = ANY(immutable)) THEN
            RAISE EXCEPTION 'Unsupported or immutable academic field' USING ERRCODE = '22023';
        END IF;
        kind := jsonb_typeof(p_payload -> key);
        IF kind = 'null' AND key <> 'description' THEN
            RAISE EXCEPTION 'Required academic field cannot be null' USING ERRCODE = '22023';
        END IF;
        IF kind <> 'null' AND (
            (key = 'is_active' AND kind <> 'boolean') OR
            (key <> 'is_active' AND kind <> 'string')
        ) THEN
            RAISE EXCEPTION 'Invalid academic field type' USING ERRCODE = '22023';
        END IF;
    END LOOP;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('academic-foundations:' || p_institution_id::text, 0)
    );
    IF p_record_id IS NOT NULL THEN
        EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE %I = $1 AND institution_id = $2 FOR UPDATE',
                       relation_name, id_column) INTO before_row USING p_record_id, p_institution_id;
        IF before_row IS NULL THEN
            RAISE EXCEPTION 'Academic record not found' USING ERRCODE = 'P0002';
        END IF;
        -- Repeated removal is safe and does not claim an additional audit transition.
        IF p_entity = 'section_subjects' AND before_row -> 'is_active' = p_payload -> 'is_active' THEN
            RETURN before_row;
        END IF;
    END IF;
    effective := COALESCE(before_row, '{}'::jsonb) || p_payload ||
        jsonb_build_object(id_column, item_id, 'institution_id', p_institution_id);
    -- Identifiers come only from the closed whitelist; payload values stay bound.
    -- Create omits is_active for assignments so the table default is always true.
    SELECT string_agg(format('%I', k), ','), string_agg(format('r.%I', k), ',')
    INTO fields, expressions
    FROM jsonb_object_keys(CASE WHEN p_record_id IS NULL THEN effective ELSE p_payload END) AS k;
    IF p_record_id IS NULL THEN
        EXECUTE format('INSERT INTO public.%I AS t (%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r RETURNING to_jsonb(t)',
                       relation_name, fields, expressions, relation_name) INTO after_row USING effective;
    ELSE
        EXECUTE format('UPDATE public.%I AS t SET (%s) = (SELECT %s FROM jsonb_populate_record(NULL::public.%I, $1) r) WHERE %I = $2 AND institution_id = $3 RETURNING to_jsonb(t)',
                       relation_name, fields, expressions, relation_name, id_column)
        INTO after_row USING effective, p_record_id, p_institution_id;
    END IF;
    INSERT INTO public.admin_audit_log (
        actor_user_id, institution_id, action, table_name, record_id, record_data, status
    ) VALUES (
        p_actor_user_id, p_institution_id,
        'academic.' || p_entity || CASE WHEN p_record_id IS NULL THEN '.create'
            WHEN before_row ->> 'is_active' = 'true' AND after_row ->> 'is_active' = 'false'
                THEN '.deactivate'
            WHEN before_row ->> 'is_active' = 'false' AND after_row ->> 'is_active' = 'true'
                THEN '.activate' ELSE '.update' END,
        relation_name, item_id::text, jsonb_build_object('before', before_row, 'after', after_row), 'success'
    );
    RETURN after_row;
END;
$$;

-- SOURCE security.sql sha256=513b133c7203998d50ae1949628e217de03d7e3c4e640cb080a47018a3c2fd91
DO $$
DECLARE relation_name text;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY['class_sections', 'section_subject_assignments'] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres', relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', relation_name);
        -- Browser roles have no policies; trusted reads are tenant-filtered.
        -- All mutation requires the authorized RPC; hard deletes have no grant.
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role', relation_name);
        EXECUTE format('CREATE TRIGGER academic_sections_validate BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.validate_academic_sections()', relation_name);
    END LOOP;
END;
$$;
ALTER FUNCTION public.validate_academic_sections() OWNER TO postgres;
ALTER FUNCTION public.guard_academic_sections_parent() OWNER TO postgres;
ALTER FUNCTION public.manage_academic_sections(uuid, uuid, text, uuid, jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.validate_academic_sections(),
    public.guard_academic_sections_parent(),
    public.manage_academic_sections(uuid, uuid, text, uuid, jsonb)
    FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.manage_academic_sections(uuid, uuid, text, uuid, jsonb) TO service_role;
NOTIFY pgrst, 'reload schema';
COMMIT;
